function stringifyValue(v) { return print(sortValueNode(v)); }
function sameArguments(a1, a2) {
  if (a1.length !== a2.length) return false;
  return a1.every((x) => { const y = a2.find((a) => a.name.value === x.name.value); if (!y) return false; return stringifyValue(x.value) === stringifyValue(y.value); });
