    const N = 200000;
    for (const [k, [f1, f2]] of Object.entries(cases)) {
      if (baseCmp(f1, f2) !== headCmp(f1, f2)) throw new Error('semantic mismatch ' + k);
      time(() => baseCmp(f1, f2), 20000); time(() => headCmp(f1, f2), 20000);
