      const doc = parse('{ ' + 'a '.repeat(n) + '}');
      const t = time(() => { const e = validate(schema, doc, [OverlappingFieldsCanBeMergedRule]); if (e.length) throw e[0]; }, 1);
      console.log('      head validate, ' + n + ' repeated "a": ' + t.toFixed(0) + 'ms');
    }
  });
});
